/* Signature Ilocano Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Mariarosa": "From Maria + Rosa compound.", "Josemaria": "From Jose + Maria compound.", "Juanpedro": "From Juan + Pedro compound.", "Anarosita": "From Ana + Rosa + -ita.", "Pedrojuan": "From Pedro + Juan.", "Rosamaria": "From Rosa + Maria.", "Marcosing": "Signature surname blending Marcos + Singson.", "Crisolaoag": "Signature surname blending Crisologo + Laoag.", "Farinvigan": "Signature surname blending Farinas + Vigan.", "Singmarcos": "Signature surname blending Singson + Marcos."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Mariarosa';
console.log(lookup(q));

